css:
[data-bz-node="s3r1"][data-bz-node]{grid-template-columns:repeat(auto-fit, minmax(300px, 1fr))}
[data-bz-node^="s3h5-r"][data-bz-node] h3{font-family:Oswald, sans-serif;font-size:18px;font-weight:600;font-style:normal;line-height:1.25;letter-spacing:0.04em;text-transform:uppercase;text-align:start;color:rgb(20, 21, 26);margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px}
[data-bz-node^="s3t6-r"][data-bz-node] p{font-family:Inter, sans-serif;font-size:15px;font-weight:400;font-style:normal;line-height:24px;letter-spacing:normal;text-transform:none;text-align:start;color:rgb(84, 86, 92);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node="s3t62"][data-bz-node] p{font-family:Inter, sans-serif;font-size:18px;font-weight:400;font-style:normal;line-height:28.8px;letter-spacing:normal;text-transform:none;text-align:start;color:rgb(20, 21, 26);margin-top:40px;margin-right:0px;margin-bottom:24px;margin-left:0px}
[data-bz-node="s3t62"][data-bz-node] a:nth-of-type(1){color:rgb(196, 18, 48);font-weight:700}
[data-bz-node="s3t62"][data-bz-node] a:nth-of-type(1):hover{color: rgb(143, 13, 33)}
[data-bz-node="s3b63"][data-bz-node] .bz-btn{margin:0;line-height:normal;background:transparent;border:0;border-radius:0;box-shadow:none;padding:0;display:inline-block;color:#C41230;text-decoration:underline;display:inline-block;background:rgb(196, 18, 48);color:rgb(255, 255, 255);text-decoration:none;font-weight:600;font-size:15px;font-family:Oswald, sans-serif;letter-spacing:0.1em;text-transform:uppercase;padding-top:18px;padding-right:32px;padding-bottom:18px;padding-left:32px}
[data-bz-node="s3b63"][data-bz-node] .bz-btn:hover{background: rgb(143, 13, 33)}
[data-bz-node="s3b63"][data-bz-node] .bz-btn:focus{outline: rgb(20, 21, 26) solid 3px; outline-offset: 3px}
[data-bz-node="s3b63"][data-bz-node] .bz-btns{margin:0;gap:0}
[data-bz-node="s3"][data-bz-node]{padding-top:clamp(56px, 8vw, 100px)}
